import{_ as a,o as s,c as n,ag as e}from"./chunks/framework.CmaAMB6e.js";const g=JSON.parse('{"title":"01 · 系统设计方法论","description":"","frontmatter":{"概念":"系统设计方法论","技能":"system-design","阶段":"1-方法论","状态":"⬜未开始","更新日期":"2026-08-01T00:00:00.000Z"},"headers":[],"relativePath":"system-design/concepts/01-design-methodology.md","filePath":"system-design/concepts/01-design-methodology.md","lastUpdated":null}'),d={name:"system-design/concepts/01-design-methodology.md"};function r(i,t,l,p,o,h){return s(),n("div",null,[...t[0]||(t[0]=[e(`<h1 id="_01-·-系统设计方法论" tabindex="-1">01 · 系统设计方法论 <a class="header-anchor" href="#_01-·-系统设计方法论" aria-label="Permalink to &quot;01 · 系统设计方法论&quot;">​</a></h1><h2 id="概念简介" tabindex="-1">概念简介 <a class="header-anchor" href="#概念简介" aria-label="Permalink to &quot;概念简介&quot;">​</a></h2><p>系统设计方法论是把一个模糊的业务诉求转化为可落地技术方案的结构化流程。前端开发通常是「需求已确定 → 实现」，而系统设计面对的是「帮我做个短链系统」——需求模糊、边界不清、规模未知。方法论的核心价值不是给出标准答案，而是提供一套<strong>提问框架</strong>：先搞清楚「要解决什么问题、服务多少人、能容忍多差」，再谈「用什么技术」。</p><p>经典流程是<strong>四步法</strong>：需求澄清 → 容量估算 → 高层设计 → 深入设计。前三步解决「做对的事」（识别问题、界定边界），最后一步解决「把事做对」（选型与细节）。对转后端的工程师，最大的认知转变是：写代码只占流程末端的一小部分，前 70% 的时间花在提问、画图、权衡取舍上。</p><p>这套方法论同时也是面试与架构评审的通用语言。学会它之后，任何新系统（信息流、聊天、秒杀）都能套用同一套骨架：先澄清、再估量、后设计，避免「上来就写表结构」的冲动。</p><h2 id="核心内容" tabindex="-1">核心内容 <a class="header-anchor" href="#核心内容" aria-label="Permalink to &quot;核心内容&quot;">​</a></h2><h4 id="_1-四步法总览" tabindex="-1">1. 四步法总览 <a class="header-anchor" href="#_1-四步法总览" aria-label="Permalink to &quot;1. 四步法总览&quot;">​</a></h4><div class="language-mermaid vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">mermaid</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">flowchart TD</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">    A[需求澄清&lt;br/&gt;功能/非功能/边界] --&gt; B[容量估算&lt;br/&gt;QPS/存储/带宽量级]</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">    B --&gt; C[高层设计&lt;br/&gt;模块划分/数据流/组件选型]</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">    C --&gt; D[深入设计&lt;br/&gt;关键决策/接口/异常场景]</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">    D --&gt;|发现新问题| A</span></span></code></pre></div><p>四步不是一次性的瀑布，而是<strong>迭代循环</strong>：深入设计时发现某个存储扛不住，就要回退到容量估算重新校准。</p><h4 id="_2-第一步-需求澄清——功能需求-vs-非功能需求" tabindex="-1">2. 第一步：需求澄清——功能需求 vs 非功能需求 <a class="header-anchor" href="#_2-第一步-需求澄清——功能需求-vs-非功能需求" aria-label="Permalink to &quot;2. 第一步：需求澄清——功能需求 vs 非功能需求&quot;">​</a></h4><p><strong>功能需求</strong>描述系统「做什么」：核心用例、用户故事、边界（哪些明确不做）。<strong>非功能需求</strong>描述系统「做得怎么样」：性能、可用性、一致性、安全、成本——这些才是系统设计真正要权衡的对象。</p><p>常见提问清单（开口前先过一遍）：</p><table tabindex="0"><thead><tr><th>问题</th><th>想探明什么</th></tr></thead><tbody><tr><td>读多还是写多？比例大概多少？</td><td>决定缓存方向、读写分离是否值得</td></tr><tr><td>实时性要求多高？数据多久可见？</td><td>决定同步调用还是消息队列/异步</td></tr><tr><td>一致性要求多强？能接受最终一致吗？</td><td>决定存储选型与架构复杂度</td></tr><tr><td>目标用户量级？预期峰值是平时的多少倍？</td><td>决定是否要分布式，还是单机+优化</td></tr><tr><td>可用性要求几个 9？挂了能接受多久？</td><td>决定冗余、容灾、降级方案</td></tr><tr><td>数据量多大、保留多久？</td><td>决定存储成本与冷热分层</td></tr><tr><td>哪些是硬性约束（合规、成本、已有系统）？</td><td>排除不现实的方案</td></tr></tbody></table><p>以「短链系统」为例：功能需求是「生成短链、重定向、点击统计」，<strong>明确不做</strong>的是「短链内容安全审核」。非功能需求是「日活 100 万、写入 QPS 峰值约 500、读取 QPS 峰值约 5000、可用性 99.9%、短链有效期 1 年」。一个关键澄清点：<strong>重定向用 301 还是 302</strong>——301 会被浏览器缓存，统计会失真但压力小；302 每次回源统计准确但多一次往返。这属于「业务决策先于技术决策」，澄清阶段就要拍板。</p><h4 id="_3-第二步-容量估算" tabindex="-1">3. 第二步：容量估算 <a class="header-anchor" href="#_3-第二步-容量估算" aria-label="Permalink to &quot;3. 第二步：容量估算&quot;">​</a></h4><p>估算的目的不是算出精确数字，而是<strong>确定量级</strong>：是单机就能扛（QPS 千级），还是需要集群（QPS 万级），还是需要分片+缓存+消息队列（QPS 十万级以上）。具体方法见 02 容量估算。短链系统的量级结论通常是：写 QPS 数百、读 QPS 数千——<strong>单机数据库 + 一层缓存即可，根本不需要 Kafka 和分片</strong>。这一步的作用就是拦住过度设计。</p><h4 id="_4-第三步-高层设计" tabindex="-1">4. 第三步：高层设计 <a class="header-anchor" href="#_4-第三步-高层设计" aria-label="Permalink to &quot;4. 第三步：高层设计&quot;">​</a></h4><p>输出一张「模块图 + 数据流图」，只画组件不画实现细节：</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>                 ┌──────────────┐</span></span>
<span class="line"><span>  用户 ──► DNS ──► 负载均衡     │</span></span>
<span class="line"><span>                 └──────┬───────┘</span></span>
<span class="line"><span>                        │</span></span>
<span class="line"><span>        ┌───────────────┼────────────────┐</span></span>
<span class="line"><span>        ▼               ▼                ▼</span></span>
<span class="line"><span> ┌──────────┐    ┌──────────┐    ┌──────────────┐</span></span>
<span class="line"><span> │ 短链服务  │    │ 统计服务  │    │ 重定向服务    │</span></span>
<span class="line"><span> │ (生成/读) │    │ (异步)    │    │ (302 跳转)    │</span></span>
<span class="line"><span> └────┬─────┘    └────┬─────┘    └─────┬────────┘</span></span>
<span class="line"><span>      │               │                │</span></span>
<span class="line"><span>      ▼               ▼                ▼</span></span>
<span class="line"><span> ┌──────────┐    ┌──────────┐    ┌──────────┐</span></span>
<span class="line"><span> │ 缓存层    │    │ 消息队列  │    │ 数据库    │</span></span>
<span class="line"><span> │ (热点短链)│    │ (统计流水)│    │ (全量映射)│</span></span>
<span class="line"><span> └──────────┘    └──────────┘    └──────────┘</span></span></code></pre></div><p>关键设计点：读路径（重定向）走缓存、写路径（生成）走发号器、统计路径异步化——<strong>不同路径用不同组件</strong>，这就是高层设计的核心：按数据流切模块。</p><h4 id="_5-第四步-深入设计" tabindex="-1">5. 第四步：深入设计 <a class="header-anchor" href="#_5-第四步-深入设计" aria-label="Permalink to &quot;5. 第四步：深入设计&quot;">​</a></h4><p>选 2-3 个关键决策点深入，并明确展示权衡：</p><table tabindex="0"><thead><tr><th>决策点</th><th>方案 A</th><th>方案 B</th><th>权衡结论</th></tr></thead><tbody><tr><td>短链 ID 生成</td><td>哈希（MD5 截取）</td><td>发号器（自增/雪花）</td><td>哈希有碰撞与长度不可控问题；发号器简单可控 → 选 B</td></tr><tr><td>重定向码</td><td>301</td><td>302</td><td>302 统计准确但压力大；量级小 → 选 302</td></tr><tr><td>存储</td><td>MySQL 单表</td><td>分库分表</td><td>亿级行内单机可扛 → 不分片，加索引即可</td></tr><tr><td>缓存</td><td>Redis</td><td>本地缓存</td><td>集群环境下本地缓存不一致 → 选 Redis</td></tr></tbody></table><p>每个决策都要回答：为什么是这个而不是那个，代价是什么。<strong>没有免费的架构</strong>——选了 Redis 就要接受缓存一致性的复杂度，选了 302 就要接受多一次跳转的延迟。</p><h4 id="_6-设计文档结构" tabindex="-1">6. 设计文档结构 <a class="header-anchor" href="#_6-设计文档结构" aria-label="Permalink to &quot;6. 设计文档结构&quot;">​</a></h4><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>1. 背景与目标（为什么做、成功标准）</span></span>
<span class="line"><span>2. 需求澄清（功能/非功能需求清单、明确不做的事）</span></span>
<span class="line"><span>3. 容量估算（QPS、存储、带宽的量级推导）</span></span>
<span class="line"><span>4. 高层架构（模块图 + 数据流图）</span></span>
<span class="line"><span>5. 深入设计（关键决策与权衡、接口契约、数据模型）</span></span>
<span class="line"><span>6. 异常场景与降级（雪崩、缓存失效、MQ 积压怎么办）</span></span>
<span class="line"><span>7. 监控与发布（关键指标、灰度策略）</span></span></code></pre></div><h4 id="_7-从-0-到-1-的检查清单" tabindex="-1">7. 从 0 到 1 的检查清单 <a class="header-anchor" href="#_7-从-0-到-1-的检查清单" aria-label="Permalink to &quot;7. 从 0 到 1 的检查清单&quot;">​</a></h4><p>设计完成不等于可以评审，提交前对照这份清单自查：</p><table tabindex="0"><thead><tr><th>检查项</th><th>自查问题</th></tr></thead><tbody><tr><td>需求闭环</td><td>功能/非功能需求是否都对应到架构决策？没对应到的说明需求被跳过了</td></tr><tr><td>量级明确</td><td>每个组件是否有 QPS/存储量级标注？还是凭感觉选的？</td></tr><tr><td>路径完整</td><td>读路径、写路径、失败路径（缓存失效/库挂/MQ 积压）是否都画了？</td></tr><tr><td>权衡成对</td><td>每个关键决策是否写明了「放弃什么」？只有好处没有代价=没想清楚</td></tr><tr><td>单点排查</td><td>图里有没有「没有冗余的必经组件」？它挂了怎么办？</td></tr><tr><td>演进空间</td><td>现在的设计能否平滑扩容？还是 3 个月后要推倒重来？</td></tr></tbody></table><h2 id="常见陷阱" tabindex="-1">常见陷阱 <a class="header-anchor" href="#常见陷阱" aria-label="Permalink to &quot;常见陷阱&quot;">​</a></h2><ul><li><strong>跳过需求澄清直接设计</strong>：最常见错误。不问「读多写多」就上 Redis，不问「一致性要求」就上最终一致，架构全部白做。</li><li><strong>功能需求与非功能需求混为一谈</strong>：只列「能做什么」却不谈「几个 9、多少 QPS」，评审时无法判断方案是否合格。</li><li><strong>把容量估算当精确计算</strong>：花一小时算 3.14159 倍的 QPS 毫无意义，量级对即可；精确留给压测。</li><li><strong>一步到位深入设计</strong>：跳过高层设计直接画表结构，导致模块边界不清、无法评审。</li><li><strong>用最新技术堆砌方案</strong>：Kafka + 分片 + 微服务堆出来的方案不一定比单机 + 缓存更好，多一层组件就多一层故障。</li><li><strong>不做权衡只说好处</strong>：只讲「用了 Redis 所以快」，不讲「一致性变差了、要多维护一个组件」，方案不完整。</li></ul><h2 id="练习建议" tabindex="-1">练习建议 <a class="header-anchor" href="#练习建议" aria-label="Permalink to &quot;练习建议&quot;">​</a></h2><ol><li><strong>基础</strong>：用四步法完整走一遍「设计一个短链系统」，每一步都写下来（含提问清单的答案），对照本教程的结论检查差异。</li><li><strong>进阶</strong>：找一个你熟悉的系统（如你公司前端的 CI 构建系统），用四步法重新设计它：澄清它的非功能需求、估算构建并发量、画高层架构图。</li><li><strong>综合</strong>：把四步法应用到「设计一个 URL 短链 + 扫码访问统计」系统，重点练习第 5 节的决策表格式，为每个决策写出「方案对比 + 理由 + 代价」。</li></ol><blockquote><p>用 <code>/practice system-design 系统设计方法论</code> 生成更多针对性练习。</p></blockquote><h2 id="前端对照" tabindex="-1">前端对照 <a class="header-anchor" href="#前端对照" aria-label="Permalink to &quot;前端对照&quot;">​</a></h2><table tabindex="0"><thead><tr><th>前端架构概念</th><th>系统设计对应</th></tr></thead><tbody><tr><td>需求评审会、明确「不做」</td><td>需求澄清：功能/非功能需求、边界</td></tr><tr><td>组件拆分（先画组件树再写代码）</td><td>高层设计：先画模块图再选组件</td></tr><tr><td>性能预算（Lighthouse 目标值）</td><td>容量估算：QPS/延迟目标量级</td></tr><tr><td>Design Review / 技术方案评审</td><td>深入设计的决策表与权衡</td></tr><tr><td>状态管理选型（Redux vs Zustand）</td><td>组件选型（Redis vs 本地缓存）</td></tr><tr><td>先搭骨架再填业务（目录结构先行）</td><td>先高层设计再深入设计</td></tr></tbody></table><h2 id="参考链接" tabindex="-1">参考链接 <a class="header-anchor" href="#参考链接" aria-label="Permalink to &quot;参考链接&quot;">​</a></h2><ul><li><a href="https://github.com/donnemartin/system-design-primer" target="_blank" rel="noreferrer">系统设计入门（GitHub 开源课程）</a></li><li><a href="https://dataintensive.net/" target="_blank" rel="noreferrer">Designing Data-Intensive Applications（DDIA）第 1 章</a></li><li><a href="https://www.designgurus.io/course/grokking-the-system-design-interview" target="_blank" rel="noreferrer">Grokking the System Design Interview（经典方法论出处）</a></li></ul>`,38)])])}const b=a(d,[["render",r]]);export{g as __pageData,b as default};
